 examples:[["Be quiet! The baby **is sleeping**.","Sessiz ol! Bebek uyuyor."],["What **are** you **doing** right now?","Şu an ne yapıyorsun?"],["I**'m reading** a great book these days.","Bu aralar harika bir kitap okuyorum."],["We**'re flying** to Antalya on Friday.","Cuma günü Antalya'ya uçuyoruz."]],
